css:
.cce-root{position:absolute;inset:0;overflow:hidden;background:var(--wa-bg, #05050a);z-index:5;font-family:"Pretendard Variable","Pretendard","Malgun Gothic",-apple-system,system-ui,sans-serif;font-size:16px;font-weight:400;font-style:normal;line-height:normal;letter-spacing:normal;color:var(--wa-text, #fff);text-align:left;text-transform:none;word-spacing:normal;-webkit-font-smoothing:antialiased}
.cce-root,.cce-root *,.cce-root *::before,.cce-root *::after{box-sizing:border-box}
.cce-root *{margin:0;padding:0;border:0 solid transparent;background:none;font:inherit;color:inherit;text-decoration:none}
.cce-root img{display:block;border:0;max-width:none}
.cce-root > [data-node-id]{will-change:transform}
.cce-root [hidden]{display:none!important}
.cce-root [data-sh-theme="dark"]{display:none!important}
.cce-root[data-theme="dark"] [data-sh-theme="dark"]{display:block!important}
.cce-root[data-theme="dark"] [data-sh-theme="dark"]{display:none!important}
.cce-root .n427_1313{word-break:break-word;align-content:stretch;display:flex;font-family:"Pretendard Variable","Pretendard","Malgun Gothic",-apple-system,system-ui,sans-serif;font-weight:420;gap:20px;align-items:center;font-style:normal;padding-top:15px;padding-bottom:15px;position:relative;flex-shrink:0;font-size:18px;width:100%}
.cce-root .n427_1313::after{content:"";position:absolute;inset:0;border:1px solid color-mix(in srgb, var(--wa-line, rgb(0 0 0)) 10%, transparent);border-radius:inherit;border-width:0 0 1px 0;pointer-events:none}
.cce-root .n427_1314{line-height:21px;overflow:hidden;position:relative;flex-shrink:0;color:var(--wa-point, #0073ff);text-overflow:ellipsis;width:95px;white-space:nowrap}
.cce-root .n427_1315{flex:1 0 0;line-height:42px;min-width:1px;position:relative;color:var(--wa-text-sub, #434859);width:825px}
.cce-root .x19{line-height:normal;margin-bottom:0}
.cce-root .x20{line-height:normal}
.cce-root [data-node-id="427:1289"],.cce-root [data-node-id="427:1317"]{height:auto!important}
.cce-root [data-node-id="427:1537"]{width:100%!important}
.cce-root [data-name^="Card/Stage"] p{letter-spacing:-0.05em;word-break:keep-all}
.cce-root[data-theme="dark"]{color:var(--wa-point, #e3e9f2)}
.cce-root[data-theme="dark"] > [data-node-id]{background:linear-gradient(180deg,var(--wa-bg, #111720) 0%,var(--wa-bg, #0b0e13) 100%)!important}
.cce-root[data-theme="dark"] [data-name="3D Scene"] img{filter:brightness(.88) saturate(.95) contrast(1.04)}
.cce-root[data-theme="dark"] [data-name="Diagram Title Patch"]{background:linear-gradient(90deg,var(--wa-point, #3d2f63) 0%,var(--wa-point, #1b2a38) 50%,var(--wa-point, #352c5d) 100%)!important;border-color:var(--wa-point, #7d7bf0)!important}
.cce-root[data-theme="dark"] [data-name="Diagram Title Patch"] p{color:var(--wa-text, #eef0fb)!important}
.cce-root[data-theme="dark"] [data-name="Side Rail"] > [data-name="Body"]{background:linear-gradient(180deg,var(--wa-surface, #151920) 47%,color-mix(in srgb, var(--wa-surface, rgb(21 25 32)) 90%, transparent) 100%)!important;border-right-color:color-mix(in srgb, var(--wa-line, rgb(255 255 255)) 6%, transparent)!important}
.cce-root[data-theme="dark"] [data-name^="Panel/"]:not([data-name="Panel/File Open"]),.cce-root[data-theme="dark"] [data-name="Popup/Detail"]{box-shadow:inset 1px 0 0 rgba(255,255,255,.04),0 12px 30px rgba(0,0,0,.35)}
.cce-root[data-theme="dark"] [data-name="Icon Button"]{box-shadow:inset 0 1px 0 rgba(255,255,255,.05)}
.cce-root[data-theme="dark"] .n427_1313::after{border-color:color-mix(in srgb, var(--wa-line, rgb(255 255 255)) 10%, transparent)}
.cce-root[data-theme="dark"] .n427_1314{color:var(--wa-point, #5ea2ff)}
.cce-root[data-theme="dark"] .n427_1315{color:var(--wa-text-sub, #c3cad6)}
